@lru_cache(maxsize=8)
def litcal_bundle_for_year(year: int) -> dict:
    """Vrati originalni LitCal JSON objekt za godinu."""
    compressed = _COMPRESSED_YEAR_BUNDLES.get(int(year))
    if not compressed:
        return {}
    if isinstance(compressed, tuple):
        compressed = ''.join(compressed)
    raw = zlib.decompress(base64.b64decode(compressed.encode("ascii")))
    return json.loads(raw.decode("utf-8"))


def litcal_events_for_year(year: int) -> list:
    bundle = litcal_bundle_for_year(year)
    return list(bundle.get('litcal') or bundle.get('Litcal') or [])

